def choose_move(observation):
    width = observation['grid_width']
    height = observation['grid_height']
    pos = observation['self_position']
    enemies = observation['opponent_position']
    resources = observation['resources']
    obstacles = set(observation['obstacles'])

    def dist(p1, p2):
        return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

    def is_valid(p):
        x,y = p
        return 0 <= x < width and 0 <= y < height and p not in obstacles

    # Find nearest resource
    target = None
    min_dist = float('inf')
    for r in resources:
        d = dist(pos, r)
        if d < min_dist:
            min_dist = d
            target = r
    # If no resources, stay put
    if target is None:
        target = pos

    # Determine move towards target
    dx = dy = 0
    if target[0] > pos[0]:
        dx = 1
    elif target[0] < pos[0]:
        dx = -1
    if target[1] > pos[1]:
        dy = 1
    elif target[1] < pos[1]:
        dy = -1

    # Prioritize valid move
    for move in [(dx,0), (-dx,0), (0,dy), (0,-dy)]:
        new_pos = (pos[0]+move[0], pos[1]+move[1])
        if is_valid(new_pos):
            return list(move)
    # If blocked, try to stay
    return [0,0]
